 [Test] public async Task FeatureFlagOffReturns503BeforeAuthAndDoesNotTouchRepository(){await using var f=Create(false);using var c=f.CreateClient();Assert.That((await c.GetAsync($"/game/v1/hives/{Guid.NewGuid()}/offline-production")).StatusCode,Is.EqualTo(HttpStatusCode.ServiceUnavailable));}
